--- Config/DefaultGame.ini ---
[/Script/EngineSettings.GeneralProjectSettings]
ProjectName=Pixel Arena
ProjectVersion=0.9.2

[/Script/UnrealEd.ProjectPackagingSettings]
Build=IfProjectHasCode
BuildConfiguration=PPBC_Shipping
UsePakFile=True
bCookAll=False
+MapsToCook=(FilePath="/Game/Maps/Arena")
+DirectoriesToAlwaysCook=(Path="/Game/Data/Effects")
+DirectoriesToAlwaysCook=(Path="/Game/Data/Palettes")
+DirectoriesToNeverCook=(Path="/Game/Dev")


--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- Tests/Check-PackagedArena.ps1 ---
$ErrorActionPreference = 'Stop'
$arenaRoot = Split-Path $PSScriptRoot -Parent
$arenaHeader = Get-Content (Join-Path $arenaRoot 'Source/PixelArena/ArenaGameMode.h') -Raw
$arenaConfig = Get-Content (Join-Path $arenaRoot 'Config/DefaultGame.ini') -Raw
$arenaFailures = @()
if ($arenaHeader -notmatch '(?s)UPROPERTY\s*\([^)]*\)\s*TObjectPtr<UArenaScoreTracker>\s+ScoreTracker\s*;') {
    $arenaFailures += 'FAIL: ScoreTracker must be a reflected strong UObject reference.'
}
if ($arenaConfig -notmatch '(?m)^\+DirectoriesToAlwaysCook=\(Path="/Game/Data/Palettes"\)\s*$') {
    $arenaFailures += 'FAIL: Packaging must always cook /Game/Data/Palettes.'
}
if ($arenaFailures.Count -gt 0) {
    $arenaFailures | Write-Output
    exit 1
}
Write-Output 'PASS: ScoreTracker is a reflected strong UObject reference.'
Write-Output 'PASS: Packaging always cooks /Game/Data/Palettes.'


--- result.json ---
{
  "crash_cause": "ScoreTracker is created with NewObject but stored in an unreflected raw UObject pointer. Its Outer does not keep it alive. Garbage collection can reclaim it, leaving a dangling pointer used by OnGoalScored. The packaged log records GC at 21:05:13 and an access violation in UArenaScoreTracker::AddPoints at 21:05:27. Fixed by retaining it in a UPROPERTY TObjectPtr<UArenaScoreTracker>. Stats is plain C++ data and retains its existing explicit ownership.",
  "no_colors_cause": "DA_Primary is loaded through a literal LoadObject path, which does not establish a cook dependency. With bCookAll=False and no palette directory in DirectoriesToAlwaysCook, the palette is absent from the package. The log explicitly reports the missing /Game/Data/Palettes/DA_Primary package, failed object load, and fallback gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook.",
  "assumptions": [
    "The supplied packaged log represents the reported failures.",
    "The palette asset exists in the full project at the source's existing path, as implied by correct editor behavior. Assets and several included headers are not supplied here."
  ],
  "validation": "Tests/Check-PackagedArena.ps1 failed on both original defects and passed after the fixes. This checks source/config invariants only. No engine is installed, so compilation, cooking, garbage-collection runtime testing, and visual validation remain unverified. A packaged runtime check should force garbage collection before scoring and verify primary colors."
}
